use crate::*;

const SECTIONS: &[BuiltinDocumentationSection] = &[
    BuiltinDocumentationSection { heading: "Behavior", paragraphs: &[
        "`formatSpec` must be text: a character row vector or string scalar. Cell arrays and multi-row character arrays are rejected.",
        "Arguments can be numeric, logical, strings, character arrays, or cell arrays containing supported scalar types. Numeric inputs accept scalar, vector, or matrix shapes; elements are flattened in column-major order.",
        "All eight integer classes are formatted directly from native storage, including full-width int64 and uint64 values that cannot be represented exactly as double.",
        "Escape sequences such as `\\n`, `\\t`, `\\r`, `\\f`, `\\b`, `\\a`, `\\v`, octal (`\\123`), and hexadecimal (`\\x7F`) are interpreted before formatting so that `sprintf` can build multi-line text easily.",
        "Width and precision may be literal digits or drawn from the input list using `*` or `.*`. Star arguments must be scalar numerics and are consumed in order.",
        "Floating `%e`/`%E` use signed, at-least-two-digit exponents. `%g`/`%G` precision counts significant digits and suppresses trailing fractional zeros; `#` retains the decimal point and significant trailing zeros. A finite floating value that cannot fit a signed integer conversion (fractional or out of range) uses scientific notation instead of truncation or clamping; RunMat retains the specified flags, width, and precision for that effective conversion.",
        "Flags match MATLAB behaviour: `-` left-aligns, `+` forces a sign, space reserves a leading space for positive numbers, `0` enables zero padding, and `#` produces alternate forms for octal, hexadecimal, and binary outputs or preserves the decimal point in floating conversions.",
        "`%%` emits a literal percent character without consuming arguments.",
        "Complex inputs are formatted as scalar text (`a+bi`) when used with `%s`; numeric conversions expect real scalars.",
        "Additional arguments beyond those required by the repeating format string raise an error to match MATLAB diagnostics.",
    ] },
    BuiltinDocumentationSection { heading: "Execution and placement", paragraphs: &[
        "Formatting executes on the CPU. GPU tensors are gathered through their exact owning provider before substitution.",
        "`sprintf` is a residency sink. When inputs include GPU tensors, RunMat gathers them back to host memory through each tensor's exact owning provider before executing the formatter. Formatting itself runs entirely on the CPU; an unavailable owner or failed transfer returns an error.",
    ] },
];

