const FAQS: &[BuiltinDocumentationFaq] = &[
    BuiltinDocumentationFaq { question: "What happens if there are not enough input values for the format specifiers?", answer: "RunMat raises `sprintf: not enough input arguments for format specifier` as soon as a placeholder cannot be satisfied. This matches MATLAB's error message." },
    BuiltinDocumentationFaq { question: "How are additional values treated when the format string contains fewer specifiers?", answer: "The format string repeats until all array elements are consumed. If the format string consumes no arguments (for example, it contains only literal text) and extra values remain, RunMat raises an error because MATLAB would also treat this as a mismatch." },
    BuiltinDocumentationFaq { question: "Can I use star (`*`) width or precision arguments with arrays?", answer: "Yes. Each `*` consumes the next scalar value from the input stream. When you provide arrays for width or precision, elements are read in column-major order the same way data arguments are." },
    BuiltinDocumentationFaq { question: "Does `sprintf` support complex numbers?", answer: "Complex values can be formatted with `%s`, which renders MATLAB's canonical `a+bi` text. Numeric conversions require real-valued inputs and raise an error for complex scalars." },
    BuiltinDocumentationFaq { question: "Are logical values supported?", answer: "Yes. Logical inputs are promoted to numeric (`1` or `0`) before formatting, so you can combine them with integer or floating-point conversions." },
    BuiltinDocumentationFaq { question: "Does `sprintf` allocate string scalars?", answer: "No. `sprintf` always returns a character row vector for MATLAB compatibility. Use `string` or `compose` if you need string scalars or string arrays." },
    BuiltinDocumentationFaq { question: "Does GPU hardware change formatting behaviour?", answer: "No. Formatting occurs on the CPU. When GPU tensors appear in the input list, RunMat gathers them to host memory before substitution so the results match MATLAB exactly." },
    BuiltinDocumentationFaq { question: "How do I emit a literal percent sign?", answer: "Use `%%` inside the format specification. The formatter converts `%%` into a single `%` without consuming an argument." },
    BuiltinDocumentationFaq { question: "How are empty inputs handled?", answer: "If all argument arrays are empty, `sprintf` returns an empty character array (`1×0`). If the format string itself is empty, the result is also empty." },
    BuiltinDocumentationFaq { question: "What happens with multi-row character arrays?", answer: "MATLAB requires `formatSpec` to be a row vector. RunMat follows the same rule: multi-row character arrays raise `sprintf: formatSpec must be a character row vector or string scalar`." },
];
